<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>2048</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #121212;
      --board: #2b2b2b;
      --empty: #3a3a3a;
      --text: #f5f5f5;
      --accent: #f0a500;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background: var(--bg);
      color: var(--text);
      font-family: Arial, Helvetica, sans-serif;
    }

    .game {
      width: min(92vw, 480px);
      text-align: center;
    }

    h1 {
      margin: 0 0 16px;
      font-size: 3rem;
      letter-spacing: 0.08em;
      color: var(--accent);
    }

    .topbar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 16px;
    }

    #score {
      min-width: 110px;
      padding: 10px 16px;
      border-radius: 6px;
      background: #242424;
      font-size: 1.2rem;
      font-weight: bold;
    }

    #reset {
      border: 0;
      border-radius: 6px;
      padding: 11px 18px;
      background: var(--accent);
      color: #171717;
      cursor: pointer;
      font-size: 1rem;
      font-weight: bold;
    }

    #reset:hover { filter: brightness(1.12); }

    #board {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 10px;
      padding: 10px;
      border-radius: 8px;
      background: var(--board);
      aspect-ratio: 1;
    }

    .tile {
      display: grid;
      place-items: center;
      border-radius: 5px;
      background: var(--empty);
      color: var(--text);
      font-size: clamp(1.35rem, 7vw, 2.6rem);
      font-weight: bold;
    }

    .tile:not(:empty) { background: #596275; }
    .tile[data-value="2"] { background: #4d6575; }
    .tile[data-value="4"] { background: #557b78; }
    .tile[data-value="8"] { background: #b56b3d; }
    .tile[data-value="16"] { background: #c4523c; }
    .tile[data-value="32"] { background: #c63d57; }
    .tile[data-value="64"] { background: #a83f75; }
    .tile[data-value="128"],
    .tile[data-value="256"],
    .tile[data-value="512"],
    .tile[data-value="1024"],
    .tile[data-value="2048"] { background: #b28a32; }

    .hint {
      margin-top: 14px;
      color: #aaa;
      font-size: 0.9rem;
    }
  </style>
</head>
<body>
  <main class="game">
    <h1>2048</h1>
    <div class="topbar">
      <div id="score">Score: 0</div>
      <button id="reset" type="button">New Game</button>
    </div>
    <div id="board" aria-label="2048 board"></div>
    <div class="hint">Use the arrow keys to move</div>
  </main>

  <script>
    (() => {
      const size = 4;
      let grid = [];
      let currentScore = 0;

      const boardElement = document.getElementById("board");
      const scoreElement = document.getElementById("score");
      const resetButton = document.getElementById("reset");

      function emptyGrid() {
        return Array.from({ length: size }, () => Array(size).fill(0));
      }

      function render() {
        boardElement.innerHTML = "";
        for (let row = 0; row < size; row++) {
          for (let col = 0; col < size; col++) {
            const value = grid[row][col];
            const tile = document.createElement("div");
            tile.className = "tile";
            tile.dataset.value = String(value);
            tile.textContent = value === 0 ? "" : String(value);
            boardElement.appendChild(tile);
          }
        }
        scoreElement.textContent = "Score: " + currentScore;
      }

      function spawnTile() {
        const empty = [];
        for (let row = 0; row < size; row++) {
          for (let col = 0; col < size; col++) {
            if (grid[row][col] === 0) empty.push([row, col]);
          }
        }
        if (!empty.length) return false;
        const [row, col] = empty[Math.floor(Math.random() * empty.length)];
        grid[row][col] = Math.random() < 0.9 ? 2 : 4;
        return true;
      }

      function reset() {
        grid = emptyGrid();
        currentScore = 0;
        spawnTile();
        spawnTile();
        render();
      }

      function slideLine(line) {
        const compact = line.filter(value => value !== 0);
        const result = [];
        let gained = 0;

        for (let i = 0; i < compact.length; i++) {
          if (compact[i] === compact[i + 1]) {
            const merged = compact[i] * 2;
            result.push(merged);
            gained += merged;
            i++;
          } else {
            result.push(compact[i]);
          }
        }

        while (result.length < size) result.push(0);
        return { line: result, gained };
      }

      function move(direction) {
        const before = grid.map(row => row.slice());
        let gained = 0;

        if (direction === "left" || direction === "right") {
          for (let row = 0; row < size; row++) {
            let line = grid[row].slice();
            if (direction === "right") line.reverse();
            const processed = slideLine(line);
            if (direction === "right") processed.line.reverse();
            grid[row] = processed.line;
            gained += processed.gained;
          }
        } else if (direction === "up" || direction === "down") {
          for (let col = 0; col < size; col++) {
            let line = [];
            for (let row = 0; row < size; row++) line.push(grid[row][col]);
            if (direction === "down") line.reverse();
            const processed = slideLine(line);
            if (direction === "down") processed.line.reverse();

            for (let row = 0; row < size; row++) {
              grid[row][col] = processed.line[row];
            }
            gained += processed.gained;
          }
        } else {
          return false;
        }

        const changed = grid.some((row, rowIndex) =>
          row.some((value, colIndex) => value !== before[rowIndex][colIndex])
        );

        if (changed) {
          currentScore += gained;
          spawnTile();
          render();
        } else {
          grid = before;
        }

        return changed;
      }

      function board() {
        return grid.map(row => row.slice());
      }

      function setBoard(arr) {
        if (
          !Array.isArray(arr) ||
          arr.length !== size ||
          arr.some(row => !Array.isArray(row) || row.length !== size)
        ) {
          throw new Error("Board must be a 4x4 array.");
        }
        grid = arr.map(row => row.map(value => Number(value) || 0));
        render();
      }

      window.game = {
        size,
        reset,
        move,
        board,
        setBoard,
        score: () => currentScore
      };

      resetButton.addEventListener("click", reset);

      document.addEventListener("keydown", event => {
        const directions = {
          ArrowLeft: "left",
          ArrowRight: "right",
          ArrowUp: "up",
          ArrowDown: "down"
        };
        if (directions[event.key]) {
          event.preventDefault();
          move(directions[event.key]);
        }
      });

      reset();
    })();
  </script>
</body>
</html>
